CREATE TABLE IF NOT EXISTS sug (id INTEGER PRIMARY KEY AUTOINCREMENT, char TEXT NOT NULL, main TEXT NOT NULL, owner TEXT NOT NULL, comment TEXT NOT NULL, lvl INTEGER, voc TEXT, created TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', note TEXT NOT NULL DEFAULT '', imported INTEGER NOT NULL DEFAULT 0, iph TEXT);
CREATE TABLE IF NOT EXISTS votes (sid INTEGER NOT NULL, voter TEXT NOT NULL, iph TEXT NOT NULL, v INTEGER NOT NULL, PRIMARY KEY (sid, voter));
CREATE INDEX IF NOT EXISTS votes_ip ON votes (sid, iph);
CREATE TABLE IF NOT EXISTS rl (k TEXT PRIMARY KEY, n INTEGER NOT NULL, reset INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS hunt (id TEXT PRIMARY KEY, target TEXT NOT NULL, created INTEGER NOT NULL, last INTEGER NOT NULL, iph TEXT);
CREATE TABLE IF NOT EXISTS reading (id INTEGER PRIMARY KEY AUTOINCREMENT, hunt TEXT NOT NULL, spot TEXT NOT NULL, x INTEGER NOT NULL, y INTEGER NOT NULL, z INTEGER NOT NULL, dir TEXT NOT NULL, dist TEXT NOT NULL, lvl TEXT NOT NULL, who TEXT NOT NULL DEFAULT '', owner TEXT NOT NULL, t INTEGER NOT NULL, iph TEXT);
CREATE INDEX IF NOT EXISTS reading_hunt ON reading (hunt, t);
CREATE TABLE IF NOT EXISTS pv (day TEXT PRIMARY KEY, n INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS uv (day TEXT NOT NULL, vh TEXT NOT NULL, PRIMARY KEY (day, vh));
